package com.vandorlabs.neoforge.screen;
import com.mojang.serialization.MapCodec;
import com.vandorlabs.screen.ScreenFamily;
import com.vandorlabs.redstone.ChannelList;
import com.vandorlabs.neoforge.redstone.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.nbt.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.*;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.ServerStartedEvent;
/** Isolated unregistered-host binding: publication, loaded membership, inert retention and real restart. */
@EventBusSubscriber(modid="vandorlabs")
public final class ScreenHostChecks {
 private static ServerLevel pendingRead;private static int readTicks;private static Fixture block;private static Block probe;private static BlockEntityType<NativeScreenEntity> type;private static ScreenFixtureCatalog catalog;private static int checks,probes;private static boolean observing;private static final BlockPos POS=new BlockPos(4200,90,4200),SAVE=POS.east(8),INERT=POS.east(12);
 private static boolean enabled(){return System.getProperty("vandorlabs.transmitterPhase","").startsWith("screen-host-");}private static void need(boolean value,String why){checks++;if(!value)throw new AssertionError("Screen host: "+why);}
 private static ScreenFixtureCatalog catalog(){if(catalog==null)catalog=new ScreenFixtureCatalog();return catalog;}
 private static final class Host extends NativeScreenEntity {Host(BlockPos pos,BlockState state){super(type,pos,state,ScreenFamily.SCREEN,catalog());}@Override public void setChanged(){if(observing&&visual()!=null)need(visual().settings()==screenSettings()&&visual().inert()==inert(),"observer sees one complete immutable publication");super.setChanged();}}
 private static final class Fixture extends BaseEntityBlock {Fixture(){super(BlockBehaviour.Properties.of().strength(1));}protected MapCodec<Fixture> codec(){return MapCodec.unit(this);}@Override public BlockEntity newBlockEntity(BlockPos pos,BlockState state){return new Host(pos,state);}}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration {@SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent event){if(!enabled())return;var id=ResourceLocation.fromNamespaceAndPath("vandorlabs","screen_host_fixture");event.register(Registries.BLOCK,h->{block=new Fixture();h.register(id,block);probe=new Block(BlockBehaviour.Properties.of().noOcclusion().isRedstoneConductor((state,world,pos)->false)){@Override protected int getDirectSignal(BlockState state,BlockGetter world,BlockPos pos,Direction face){probes++;return 7;}@Override protected int getSignal(BlockState state,BlockGetter world,BlockPos pos,Direction face){probes++;return 7;}@Override protected boolean isSignalSource(BlockState state){return true;}};h.register(ResourceLocation.fromNamespaceAndPath("vandorlabs","screen_host_probe"),probe);});event.register(Registries.BLOCK_ENTITY_TYPE,h->{type=BlockEntityType.Builder.<NativeScreenEntity>of(Host::new,block).build(null);h.register(id,type);});}}
 private static NativeScreenEntity host(ServerLevel world,BlockPos pos){return (NativeScreenEntity)world.getBlockEntity(pos);}
 private static final class Source implements NativeChannelMember {final NativeScreenEntity owner;Source(NativeScreenEntity owner){this.owner=owner;}public BlockEntity channelBlockEntity(){return owner;}public ChannelList getRedstoneChannels(){return ChannelList.of(73101);}public ChannelList transmittedChannels(){return getRedstoneChannels();}public int transmissionRange(){return 16;}public int localSignalLevel(int channel){return 15;}public void setChannelLevel(int level){}}
 @SubscribeEvent public static void start(ServerStartedEvent event)throws Exception{if(!enabled())return;ServerLevel world=event.getServer().overworld();for(int x=262;x<=263;x++)for(int z=262;z<=263;z++){world.getChunk(x,z);world.setChunkForced(x,z,true);}boolean read=System.getProperty("vandorlabs.transmitterPhase").endsWith("read");observing=true;if(read){pendingRead=world;return;}
  if(!read){world.setBlock(POS,block.defaultBlockState(),2);world.setBlock(POS.north(),probe.defaultBlockState(),2);NativeScreenEntity receiver=host(world,POS);probes=0;receiver.onLoad();need(probes==0,"onLoad does not sample neighbors");NativeRedstoneChannels.flush(world);need(probes>0&&receiver.visual().effectivePower()==7,"deferred loaded registration samples physical power probes="+probes+" power="+receiver.visual().effectivePower());CompoundTag data=receiver.saveWithoutMetadata(world.registryAccess());data.putIntArray("RedstoneChannels",new int[]{73101});data.putString("ForeignRoot","retained");CompoundTag caps=new CompoundTag();caps.putString("ExternalOwner","opaque");data.put("ForgeCaps",caps);data.putString("DisplayActivation","future activation envelope");CompoundTag controls=new CompoundTag(),row=new CompoundTag();ListTag rows=new ListTag();row.putString("Label","Pulse");row.putBoolean("Pulse",true);row.putIntArray("RedstoneChannels",new int[]{73102});row.putLong("PulseUntil",200);row.putString("FutureRow","opaque");rows.add(row);controls.put("Rows",rows);controls.putBoolean("Enabled",true);controls.putString("Title","Saved control");data.put("RedstonePrimary",controls);CompoundTag nativeData=new CompoundTag();nativeData.putString("PrivateNative","retained");data.put("NeoForgeData",nativeData);CompoundTag originalData=data.copy();receiver.loadWithComponents(data,world.registryAccess());receiver.getPersistentData().putString("LiveMutation","current");need(data.equals(originalData),"superclass persistent data cannot mutate original input");NativeRedstoneChannels.flush(world);need(receiver.controls(0).rows().get(0).pulseUntil()==200,"saved row authority retained");var frozen=receiver.visual();world.setBlock(SAVE,block.defaultBlockState(),2);NativeScreenEntity sourceOwner=host(world,SAVE);Source source=new Source(sourceOwner);NativeRedstoneChannels.channelsChanged(source);need(receiver.visual().effectivePower()==15&&receiver.screenSettings().channelLevel()==15&&receiver.screenSettings().scalar().channelSignal,"actual native bank delivers numeric receiver level");need(receiver.visual().geometryRevision()==frozen.geometryRevision(),"power delivery reuses geometry revision");CompoundTag saved=receiver.saveWithoutMetadata(world.registryAccess()),update=receiver.getUpdateTag(world.registryAccess());need(saved.getCompound("NeoForgeData").getString("LiveMutation").equals("current"),"live superclass persistent data saves current state");need(saved.getCompound("ForgeCaps").equals(caps)&&saved.getString("ForeignRoot").equals("retained")&&saved.getString("DisplayActivation").equals("future activation envelope")&&saved.getCompound("RedstonePrimary").getList("Rows",10).getCompound(0).getString("FutureRow").equals("opaque"),"private snapshots preserve unsupported data");need(!update.contains("NeoForgeData")&&!update.contains("ForgeCaps")&&!update.contains("ForeignRoot")&&!update.contains("DisplayActivation")&&!update.getCompound("RedstonePrimary").getList("Rows",10).getCompound(0).contains("FutureRow"),"public projection excludes opaque root and nested bytes");need(update.getIntArray("RedstoneChannels")[0]==73101&&update.getCompound("RedstonePrimary").getList("Rows",10).getCompound(0).getLong("PulseUntil")==200,"public projection includes required editor/runtime fields");NativeRedstoneChannels.unregister(source);need(receiver.screenSettings().channelLevel()==0&&receiver.visual().effectivePower()==7,"withdrawal leaves loaded physical power");world.setBlock(SAVE.north(),probe.defaultBlockState(),2);sourceOwner.loadWithComponents(saved,world.registryAccess());NativeRedstoneChannels.flush(world);
   world.setBlock(INERT,block.defaultBlockState(),2);CompoundTag bad=new CompoundTag(),forge=new CompoundTag(),modules=new CompoundTag(),item=new CompoundTag();item.putString("id","future:owned_module");item.putByte("Count",(byte)1);modules.put("main",item);forge.put("VandorTransmitters",modules);bad.put("ForgeData",forge);bad.putString("UnknownFuture","retained");host(world,INERT).getPersistentData().putString("OldLiveData","must-not-leak");CompoundTag originalBad=bad.copy();host(world,INERT).loadWithComponents(bad,world.registryAccess());need(bad.equals(originalBad),"inert load leaves original input unchanged");need(host(world,INERT).inert()&&!host(world,INERT).isChannelMemberActive()&&host(world,INERT).getRedstoneChannels().isEmpty(),"unsupported ownership stays inert");need(host(world,INERT).saveWithoutMetadata(world.registryAccess()).equals(bad),"failed snapshot is original without partial defaults");
  }
  observing=false;System.out.println("[vandorlabs][screen-host] "+(read?"read":"write")+" PASS checks="+checks+" prototype binding only; control actions/joined power/rendering not yet bound");event.getServer().halt(false);
 }

 @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.LevelTickEvent.Post event){if(event.getLevel()!=pendingRead||++readTicks<5)return;ServerLevel world=pendingRead;pendingRead=null;verifyRead(world);observing=false;System.out.println("[vandorlabs][screen-host] read PASS checks="+checks+" actual chunk onLoad/deferred channels after five level ticks");world.getServer().halt(false);}
 private static void verifyRead(ServerLevel world){NativeScreenEntity restored=host(world,SAVE);need(restored!=null&&!restored.inert()&&restored.screenSettings().channels().equals(ChannelList.of(73101))&&restored.controls(0).rows().get(0).pulseUntil()==200,"actual process restart restores screen/control choices");CompoundTag saved=restored.saveWithoutMetadata(world.registryAccess());need(saved.getString("ForeignRoot").equals("retained")&&saved.getCompound("ForgeCaps").getString("ExternalOwner").equals("opaque")&&saved.getString("DisplayActivation").equals("future activation envelope"),"restart retains opaque envelope");need(host(world,INERT).inert()&&host(world,INERT).saveWithoutMetadata(world.registryAccess()).getString("UnknownFuture").equals("retained"),"actual restart preserves inert failed snapshot");NativeRedstoneChannels.flush(world);need(restored.visual().effectivePower()==7,"restart samples physical power only after deferred flush");
 }
}
